+        margin: 0 0 0.75rem;
+        font-size: clamp(1.75rem, 7vw, 2.35rem);
+        line-height: 1.1;
+        letter-spacing: -0.04em;
+      }
+
+      .intro,
+      .helper,
+      .required-note {
+        color: var(--muted);
+      }
+
+      .intro {
+        margin: 0 0 1.5rem;
+        line-height: 1.6;
+      }
+
+      .required-note {
+        margin: 0 0 1rem;
+        font-size: 0.9rem;
+      }
+
+      .form-field {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.2rem 0.75rem;
+        padding: 1rem;
+        background: var(--panel-strong);
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+      }
+
+      .form-field input {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--accent);
+      }
+
+      .form-field label {
+        font-weight: 700;
+        line-height: 1.45;
+      }
+
+      .required-marker {
+        color: var(--error);
+        font-weight: 800;
+      }
+
+      .helper,
+      .error {
+        grid-column: 2;
+        margin: 0.15rem 0 0;
+        font-size: 0.93rem;
+        line-height: 1.5;
+      }
+
+      .error {
+        color: var(--error);
+      }
+
+      .error[hidden] {
+        display: none;
+      }
+
+      button {
+        width: 100%;
+        margin-top: 1.25rem;
+        padding: 0.9rem 1.2rem;
+        color: #ffffff;
+        font: inherit;
+        font-weight: 800;
+        background: linear-gradient(135deg, var(--accent), #6d28d9);
+        border: 0;
+        border-radius: 999px;
+        box-shadow: 0 0.75rem 1.8rem rgba(109, 40, 217, 0.35);
+        cursor: pointer;
+      }
+
+      button:hover {
+        background: linear-gradient(135deg, var(--accent-strong), #7c3aed);
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 1rem 0 0;
+        color: var(--success);
+        font-weight: 700;
+      }
+
+      @media (prefers-reduced-motion: reduce) {
+        *,
+        *::before,
+        *::after {
+          scroll-behavior: auto !important;
+          transition-duration: 0.01ms !important;
+          animation-duration: 0.01ms !important;
+          animation-iteration-count: 1 !important;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        button {
+          border: 1px solid ButtonText;
+          box-shadow: none;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content" class="page-shell">
+      <div id="app"></div>
+    </main>
+
+    <script>
+      const ConsentCheckbox = () => `
+        <div class="form-field">
+          <input
+            id="terms-consent"
+            name="termsConsent"
+            type="checkbox"
+            required
+            aria-describedby="terms-helper terms-error"
+          >
+          <label for="terms-consent">
+            I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
+          </label>
+          <p id="terms-helper" class="helper">Required to continue with your submission.</p>
+          <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use before submitting.</p>
+        </div>
+      `;
+
+      const ConsentForm = () => `
+        <section class="card" aria-labelledby="form-title">
+          <h1 id="form-title">Review and continue</h1>
+          <p class="intro">Confirm that you accept the terms before sending your consent.</p>
+          <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
+          <form id="consent-form" novalidate>
+            ${ConsentCheckbox()}
+            <button type="submit">Submit consent</button>
+            <p id="form-status" class="status" aria-live="polite"></p>
+          </form>
+        </section>
+      `;
+
+      const mountConsentForm = (root) => {
+        root.innerHTML = ConsentForm();
+
+        const form = root.querySelector("#consent-form");
+        const checkbox = root.querySelector("#terms-consent");
+        const error = root.querySelector("#terms-error");
+        const status = root.querySelector("#form-status");
+
+        const setValidity = () => {
+          const isValid = checkbox.checked;
+          checkbox.setAttribute("aria-invalid", String(!isValid));
+          error.hidden = isValid;
+          return isValid;
+        };
+
+        checkbox.addEventListener("change", () => {
+          setValidity();
+          if (checkbox.checked) {
+            status.textContent = "";
+          }
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          status.textContent = "";
+
+          if (!setValidity()) {
+            checkbox.focus();
+            return;
+          }
+
+          status.textContent = "Consent submitted.";
+        });
+      };
+
+      mountConsentForm(document.querySelector("#app"));
+    </script>
+  </body>
+</html>
*** End Patch
