        border-radius: 1.5rem;
        box-shadow: 0 1.25rem 4rem rgba(0, 0, 0, 0.45);
        backdrop-filter: blur(18px);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.75rem, 7vw, 2.35rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

