const axePath = require.resolve('/tmp/a11y-node/node_modules/axe-core/axe.min.js');
const htmlPath = path.resolve('index.html');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 320, height: 700 } });
  await page.goto(`file://${htmlPath}`, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const summarize = (results) => results.violations
    .filter((v) => !v.tags.includes('best-practice'))
    .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }));

  const initial = summarize(await page.evaluate(async () => await window.axe.run()));

  await page.locator('button[type="submit"]').click();
  const focusedId = await page.evaluate(() => document.activeElement.id);
  const invalidState = await page.locator('#terms-consent').getAttribute('aria-invalid');
  const errorHidden = await page.locator('#terms-error').evaluate((el) => el.hidden);
  const afterInvalidSubmit = summarize(await page.evaluate(async () => await window.axe.run()));

  await page.locator('#terms-consent').check();
  const fixedInvalidState = await page.locator('#terms-consent').getAttribute('aria-invalid');
  const fixedErrorHidden = await page.locator('#terms-error').evaluate((el) => el.hidden);
  await page.locator('button[type="submit"]').click();
  const statusText = await page.locator('#form-status').textContent();
  const afterValidSubmit = summarize(await page.evaluate(async () => await window.axe.run()));

  const assertions = [
    ['initial axe', initial.length === 0, initial],
    ['invalid-submit axe', afterInvalidSubmit.length === 0, afterInvalidSubmit],
    ['valid-submit axe', afterValidSubmit.length === 0, afterValidSubmit],
    ['invalid submit focuses checkbox', focusedId === 'terms-consent', focusedId],
    ['invalid submit marks checkbox invalid', invalidState === 'true', invalidState],
    ['invalid submit shows error', errorHidden === false, errorHidden],
    ['checking clears invalid state', fixedInvalidState === 'false', fixedInvalidState],
    ['checking hides error', fixedErrorHidden === true, fixedErrorHidden],
    ['valid submit announces status', statusText.trim() === 'Consent submitted.', statusText]
  ];

  await browser.close();

  const failures = assertions.filter(([, ok]) => !ok);
  console.log(JSON.stringify({ failures: failures.map(([name, , detail]) => ({ name, detail })) }));
  process.exit(failures.length ? 1 : 0);
})().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(2);
});
